if.script:
const base = '/qapps/Manufacturing/Reports/'
const query = parameters => Object.entries(parameters || {}).filter(([, value]) => value != null && value !== '')
    .map(([name, value]) => encodeURIComponent(name) + '=' + encodeURIComponent(String(value))).join('&')
kpis = Array.from(dashboard?.kpis || []).map(kpi => ({kpiId: kpi.kpiId, title: kpi.title,
    valueText: kpi.valueText, detail: kpi.detail || '', url: base + kpi.reportName + '?' + query(kpi.parameters)}))
kpiStatus = dashboard?.asOf ? {asOfText: dashboard.asOfText, periodText: dashboard.scope?.periodText,
    complete: dashboard.complete, partitionsText: dashboard.partitionsText, withheldText: dashboard.withheldText}
    : {unavailable: true}
const completed = kpis.find(kpi => kpi.kpiId === 'completed')
if (dashboard?.completedCount != null) summary.completedCount = dashboard.completedCount
completedLink = completed ? completed.url : null
